  "bond-ionic-covalent-formation": "<div class=\"mx-auto max-w-md rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 320 200\" class=\"w-full\" role=\"img\" aria-label=\"Two ways atoms bond. Ionic bonding: a sodium atom transfers its single outer electron to a chlorine atom, forming a positive sodium ion and a negative chloride ion that attract each other. Covalent bonding: two chlorine atoms share a pair of electrons so each reaches a full outer shell.\"><text x=\"160\" y=\"16\" text-anchor=\"middle\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"10\" font-weight=\"700\">Ionic bond — electron TRANSFER</text><circle cx=\"50\" cy=\"50\" r=\"18\" class=\"fill-indigo-100/70 stroke-indigo-500 dark:fill-indigo-900/40\" stroke-width=\"1.4\"></circle><text x=\"50\" y=\"54\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"11\" font-weight=\"700\">Na</text><circle cx=\"50\" cy=\"30\" r=\"2.6\" class=\"fill-rose-500\"></circle><circle cx=\"150\" cy=\"50\" r=\"18\" class=\"fill-indigo-100/70 stroke-indigo-500 dark:fill-indigo-900/40\" stroke-width=\"1.4\"></circle><text x=\"150\" y=\"54\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"11\" font-weight=\"700\">Cl</text><circle cx=\"168.0\" cy=\"50.0\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"161.3\" cy=\"64.0\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"146.3\" cy=\"67.6\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"134.0\" cy=\"58.2\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"133.6\" cy=\"42.7\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"145.3\" cy=\"32.6\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><circle cx=\"160.6\" cy=\"35.4\" r=\"2.4\" class=\"fill-slate-700 dark:fill-slate-200\"></circle><defs><marker id=\"eArrow\" markerWidth=\"7\" markerHeight=\"7\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" class=\"fill-rose-600 dark:fill-rose-400\"></path></marker></defs><line x1=\"72\" y1=\"34\" x2=\"128\" y2=\"44\" class=\"stroke-rose-600 dark:stroke-rose-400\" stroke-width=\"1.4\" marker-end=\"url(#eArrow)\"></line><text x=\"100\" y=\"30\" text-anchor=\"middle\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"7.5\">1 e⁻</text><text x=\"200\" y=\"46\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"11\" font-weight=\"700\">→ Na⁺ + Cl⁻</text><text x=\"200\" y=\"62\" class=\"fill-slate-500\" font-size=\"7.5\">ions attract</text><line x1=\"20\" y1=\"100\" x2=\"300\" y2=\"100\" class=\"stroke-slate-300 dark:stroke-slate-600\" stroke-width=\"0.8\" stroke-dasharray=\"3 3\"></line><text x=\"160\" y=\"122\" text-anchor=\"middle\" class=\"fill-indigo-600 dark:fill-indigo-300\" font-size=\"10\" font-weight=\"700\">Covalent bond — electron SHARING</text><circle cx=\"118\" cy=\"160\" r=\"18\" class=\"fill-indigo-100/70 stroke-indigo-500 dark:fill-indigo-900/40\" stroke-width=\"1.4\"></circle><text x=\"112\" y=\"164\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"11\" font-weight=\"700\">Cl</text><circle cx=\"202\" cy=\"160\" r=\"18\" class=\"fill-indigo-100/70 stroke-indigo-500 dark:fill-indigo-900/40\" stroke-width=\"1.4\"></circle><text x=\"208\" y=\"164\" text-anchor=\"middle\" class=\"fill-slate-700 dark:fill-slate-100\" font-size=\"11\" font-weight=\"700\">Cl</text><circle cx=\"155\" cy=\"154\" r=\"2.8\" class=\"fill-rose-500\"></circle><circle cx=\"155\" cy=\"166\" r=\"2.8\" class=\"fill-rose-500\"></circle><text x=\"160\" y=\"190\" text-anchor=\"middle\" class=\"fill-slate-500\" font-size=\"7.5\">a shared pair = one covalent bond (Cl–Cl)</text></svg></div>",
